#include "/Project/ClearwaterWaves.ush"
// clearwater optics: Fresnel reflection + transmitted floor + in-scatter + glints.
const float IOR = 1.3335;
float3 SigT = SigmaA + SigmaS;
float3 Nw = N;
float nv = dot(Nw, V);
if (nv < 0.02) { Nw = normalize(Nw + V * (0.02 - nv)); nv = dot(Nw, V); }
float F = CW_FRESNEL(nv, IOR);
float3 Rr = reflect(-V, Nw); Rr.y = abs(Rr.y);
float3 Refl = CW_SKY(Rr, SunDir) * 1.25;
// Beckmann glints widened by the slope variance (clearwater LEAN trick).
float3 Hv = normalize(V + SunDir);
float nh = max(dot(Nw, Hv), 0.0);
float nl = max(dot(Nw, SunDir), 0.0);
float a2 = 0.00012 + GlintWidening;
float c2 = max(nh * nh, 1e-4);
float D = exp(-((1.0 - c2) / c2) / max(a2, 1e-6)) / (3.14159265 * max(a2, 1e-6) * c2 * c2);
float Vis = 0.5 / max(nl * sqrt(nv * nv * (1.0 - a2) + a2)
                    + nv * sqrt(nl * nl * (1.0 - a2) + a2), 1e-5);
float3 Spec = SunColor.rgb * min(D * Vis * CW_FRESNEL(max(dot(Hv, V), 0.0), IOR) * nl, 12000.0);
float Ts = 1.0 - CW_FRESNEL(max(SunDir.y, 0.0), IOR);
float3 SunT = refract(-SunDir, float3(0, 0, 1), 1.0 / IOR);
float Path = DepthCm * 0.01 / max(-SunT.z, 0.05);
// Caustics arrive as a single scalar the material graph sampled and averaged; a
// Custom node cannot take a Texture2D input, so the sampling happens outside.
float Caus = max(Caustic, 0.0);
float3 Floor = SceneColor * Ts * exp(-SigT * Path) * Caus;
float3 Lmid = SunColor.rgb * Ts * exp(-SigT * Path * 0.5)
           * ((1.0 - 0.64) / (12.566 * pow(max(1.0 + 0.64 - 1.6 * dot(SunT, -V), 1e-4), 1.5)) + 0.02);
float3 Lin = (SigmaS / max(SigT, 1e-4)) * Lmid * 3.2 * (1.0 - exp(-SigT * Path));
float3 C = F * Refl + (1.0 - F) * (Floor + Lin) + Spec;
// Lens diffraction star on the sun glints (clearwater buildPSF cone, closed form).
float facing = saturate(dot(normalize(V), SunDir));
float Glint = pow(facing, 220.0) * 14.0;
float2 gd = (ScreenUV - SunScreen) * float2(Aspect, 1.0);
float gr = length(gd);
float2 gdir = gr > 1e-5 ? gd / gr : float2(0.0, 0.0);
float gcore = exp(-(gr * gr) / max(GlareRadius * GlareRadius * 0.08, 1e-8));
float gtail = GlareRadius / (gr + GlareRadius * 0.35);
float gstar = 0.40 + 0.60 * pow(abs(cos(3.0 * atan2(gdir.y, gdir.x))), 3.0);
float3 G = lerp(GlareCool, GlareWarm, saturate(gr / max(GlareRadius * 0.5, 1e-4)))
          * gstar * (gcore + gtail * gtail * 0.35) * Glint;
return C + G;

