#include "/Project/ClearwaterWaves.ush"
// Push the scene through the water column, same optics as the surface transmission.
const float IOR = 1.3335;
float3 SigT = SigmaA + SigmaS;
float Path = max(distance(CamPos, PixelPos) * 0.01, 0.0);
float3 toCam = normalize(CamPos - PixelPos);
float CosView = saturate(-toCam.z);
float Entry = 1.0 - CW_FRESNEL(CosView, IOR);
float3 SunT = refract(-SunDir, float3(0, 0, 1), 1.0 / IOR);
float3 Lmid = SunColor.rgb * Entry * exp(-SigT * Path * 0.5)
           * ((1.0 - 0.64) / (12.566 * pow(max(1.0 + 0.64 - 1.6 * dot(SunT, float3(0,0,-1)), 1e-4), 1.5)) + 0.02);
float3 Lin = (SigmaS / max(SigT, 1e-4)) * Lmid * 3.2 * (1.0 - exp(-SigT * Path));
return SceneColor * Entry * exp(-SigT * Path) + Lin;
